namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int CentsFor(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(TierPoints(tier) + OrderSizePoints(subtotalCents), CeilingPoints);
        return subtotalCents * points / 100;
    }

    private static int TierPoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9
    };

    private static int OrderSizePoints(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
